public static String findRootPrefix(final Iterable<String> entryNames) {
   String nested = null;
   int nestedCount = 0;

   for (String name : entryNames) {
      if (name.equals("pack.mcmeta")) {
         return "";
      }

      if (name.endsWith("/pack.mcmeta") && name.indexOf('/') == name.length() - "/pack.mcmeta".length() && !name.startsWith("__MACOSX/")) {
         nested = name.substring(0, name.indexOf('/'));
         nestedCount++;
      }
   }

   return nestedCount == 1 ? nested : "";
}

